fix.code:
abstract class Report {
    private final String title;

    protected Report(String title) {
        this.title = title;
        System.out.println("Tạo báo cáo: " + title);
    }
}

final class SalesReport extends Report {
    private final String region;

    SalesReport(String region) {
        super("Doanh số " + region.toUpperCase());
        this.region = region;
    }
}
